// server-shared: calendar days in IST (the app's users are in India).
// shortcut: fixed +05:30 for every user; switch to profile time zones if we launch outside India.
const IST_MS = 330 * 60_000;

/** YYYY-MM-DD in IST for the given instant. */
export function istDay(at: Date = new Date()): string {
  return new Date(at.getTime() + IST_MS).toISOString().slice(0, 10);
}

/** UTC ISO bounds [from, to) of an IST calendar day. */
export function istDayRange(day: string): { from: string; to: string } {
  const start = Date.parse(`${day}T00:00:00.000Z`) - IST_MS;
  return { from: new Date(start).toISOString(), to: new Date(start + 86_400_000).toISOString() };
}

export function addDays(day: string, n: number): string {
  return new Date(Date.parse(`${day}T00:00:00.000Z`) + n * 86_400_000).toISOString().slice(0, 10);
}
